package com.ruoyi.majorpilot.report.claims;
import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.report.core.*;
import com.ruoyi.majorpilot.shared.CanonicalJson;
import java.util.*;
import static com.ruoyi.majorpilot.report.core.ReportTestFixtures.*;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
class EvidenceDeriverTest {
    final EvidenceRuleRegistry registry=new EvidenceRuleRegistry();final EvidenceDeriver deriver=new EvidenceDeriver(JSON,registry);
    EvidenceDeriver.Input input(List<String> interest,String wish){var e=EvidenceRuleRegistry.production().getFirst();var answers=JSON.createObjectNode();answers.set("interestingStepKeys",JSON.valueToTree(interest));if(wish!=null)answers.put("continueSimilarWork",wish);answers.put("reflectionNote","IGNORED_PRIVATE_TEXT");var r=new EvidenceDeriver.ReflectionSource(id(1),id(2),id(3),e.taskVersionId(),1,2,2,CanonicalJson.hash(JSON,answers),answers,NOW);var self=new HashMap<String,JsonNode>();self.put("reflection:interestingStepKeys",answers.get("interestingStepKeys"));if(wish!=null)self.put("reflection:continueSimilarWork",answers.get("continueSimilarWork"));return new EvidenceDeriver.Input(id(1),id(2),id(3),e.taskVersionId(),e.manifestSha256(),e.majorCode(),e.questionSetVersion(),e.closedSchema(),e.oldRule(),e.newRule(),r,self);}
    @Test void mutuallyExclusiveRulesAndNoInterestBoundary(){for(String wish:List.of("YES","NO","UNSURE")){var d=deriver.derive(input(List.of("a3-errors"),wish)).orElseThrow();assertEquals(wish.equals("YES")?"INTEREST_WITH_CONTINUATION":"INTEREST_WITHOUT_CONFIRMED_CONTINUATION",d.value().path("derivationRuleKey").asText());assertFalse(d.value().toString().contains("IGNORED_PRIVATE_TEXT"));assertEquals(List.of("BOUNDED_INTERPRETATION"),d.claims());assertTrue(deriver.derive(input(List.of("NONE"),wish)).isEmpty());}}
    @Test void invalidEnumsAndMixedNoneNeverSilentlyBecomeMissingEvidence(){for(var interests:List.of(List.<String>of(),List.of("NONE","a3-errors"),List.of("foreign-step"),List.of("a3-errors","a3-errors")))assertThrows(ReportInputException.class,()->deriver.derive(input(interests,"YES")));assertThrows(ReportInputException.class,()->deriver.derive(input(List.of("a3-errors"),null)));assertThrows(ReportInputException.class,()->deriver.derive(input(List.of("a3-errors"),"MAYBE")));}
    @Test void exactCompatibilityAndRevisionHashOwnerFences(){var original=input(List.of("a3-errors"),"YES");var r=original.reflection();var foreign=new EvidenceDeriver.ReflectionSource(id(99),r.runId(),r.decisionProfileId(),r.taskVersionId(),r.sourceId(),r.revision(),r.expectedRevision(),r.expectedSha256(),r.answers(),r.observedAt());var bad=new EvidenceDeriver.Input(original.studentPublicId(),original.runId(),original.decisionProfileId(),original.taskVersionId(),original.taskManifestSha256(),original.majorCode(),original.questionSetVersion(),original.closedSchema(),original.sourceRule(),original.effectiveRule(),foreign,original.selfReports());assertThrows(ReportInputException.class,()->deriver.derive(bad));assertThrows(ReportInputException.class,()->registry.forNewClose(original.majorCode(),original.taskVersionId(),"0".repeat(64),original.questionSetVersion()));assertThrows(ReportInputException.class,()->registry.requireCompatible("evidence-v1","evidence-v3",original.closedSchema(),original.majorCode(),original.taskVersionId(),original.taskManifestSha256(),original.questionSetVersion()));}
    @Test void legacyRuleDoesNotGetNewInterpretationAndRepeatedInputIsStable(){var i=input(List.of("a4-configure","a3-errors"),"YES");var old=new EvidenceDeriver.Input(i.studentPublicId(),i.runId(),i.decisionProfileId(),i.taskVersionId(),i.taskManifestSha256(),i.majorCode(),i.questionSetVersion(),i.closedSchema(),i.sourceRule(),i.sourceRule(),i.reflection(),i.selfReports());assertTrue(deriver.derive(old).isEmpty());assertEquals(deriver.derive(i),deriver.derive(i));}
}
